function withQuery(path: string, query: Record<string, string | number | boolean>): string {
  const params = new URLSearchParams();
  Object.entries(query).forEach(([key, value]) => {
    params.set(key, String(value));
  });
  const qs = params.toString();
  return qs ? `${path}?${qs}` : path;
}

export async function listHd1Invoices(
  query: Record<string, string | number | boolean>,
): Promise<Hd1InvoiceListItem[]> {
  const res = await apiClient.get<BffResponse<Hd1InvoiceListItem[]>>(withQuery(BASE, query));
  return unwrap(res);
}

export async function getHd1Invoice(sttRec: string): Promise<Hd1Invoice> {
  const res = await apiClient.get<BffResponse<Hd1Invoice>>(`${BASE}/${encodeURIComponent(sttRec)}`);
  return unwrap(res);
}

export async function createHd1Invoice(body: Hd1InvoiceWrite): Promise<Hd1Invoice> {
  const res = await apiClient.post<BffResponse<Hd1Invoice>>(BASE, body);
  return unwrap(res);
}

export async function updateHd1Invoice(sttRec: string, body: Hd1InvoiceWrite): Promise<Hd1Invoice> {
  const res = await apiClient.put<BffResponse<Hd1Invoice>>(`${BASE}/${encodeURIComponent(sttRec)}`, body);
  return unwrap(res);
}
