function showMoney(value: number | null | undefined): string {
  return new Intl.NumberFormat('vi-VN', { maximumFractionDigits: 4 }).format(value ?? 0);
}

function parseNum(raw: string): number | null {
  const text = raw.trim();
  if (!text) return null;
  const value = Number(text.replace(',', '.'));
  return Number.isFinite(value) ? value : null;
}

function round4(value: number): number {
  return Math.round(value * 10000) / 10000;
}

function numText(value: number | null | undefined): string {
  if (value == null) return '';
  return String(value);
}

function textOrNull(value: string): string | null {
  const text = value.trim();
  return text ? text : null;
}

function numOrNull(value: string): number | null {
  return parseNum(value);
}

function fillDerived(line: LineState, tyGiaRaw: string): LineState {
  const next = { ...line };
  if (!next.tienNt2.trim()) {
    const qty = parseNum(next.soLuong);
    const gia = parseNum(next.giaNt2);
    if (qty != null && gia != null) next.tienNt2 = String(round4(qty * gia));
  }
  if (!next.ckNt.trim()) {
    const pt = parseNum(next.ptCk);
    const tien = parseNum(next.tienNt2);
    if (pt != null && tien != null) next.ckNt = String(round4(tien * Math.round(pt) / 100));
  }
  if (!next.ck.trim()) {
    const ckNt = parseNum(next.ckNt);
    if (ckNt != null) {
      const ty = parseNum(tyGiaRaw) ?? 0;
      next.ck = String(ty === 0 ? 0 : round4(ckNt * ty));
    }
  }
  return next;
}

function previewTien2(line: LineState, tyGiaRaw: string): number {
  const gia2 = parseNum(line.gia2) ?? 0;
  const qty = parseNum(line.soLuong) ?? 0;
  const ty = parseNum(tyGiaRaw) ?? 0;
  const tienNt = parseNum(line.tienNt2) ?? 0;
  if (gia2 !== 0) return round4(qty * gia2);
  if (ty !== 0) return round4(tienNt * ty);
  return 0;
}

